settings.custom_css:
selector {
    padding: 0 !important;
    margin-top: 1px !important;
    margin-bottom: 1px !important;
    align-items: flex-start !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
    cursor: pointer !important;
    transition: background-color 0.2s ease !important;
    position: relative !important;
}

selector:hover {
    background-color: rgba(0, 0, 0, 0.02) !important;
}

selector * {
    box-sizing: border-box !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
}

/* Remove min-height específico que aparece no DevTools */
selector .elementor-element,
selector .elementor-widget,
selector .elementor-widget-container,
selector .elementor-container {
    min-height: 0 !important;
    height: auto !important;
}

/* JavaScript para tornar clicável */
selector:after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 1;
}

selector {
    max-width: 120px !important;
    width: 15% !important;
    flex-shrink: 0;
    align-self: flex-start !important;
    margin: 0 8px 0 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
}

selector img {
    width: 100% !important;
    max-width: 120px !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
    object-fit: cover;
    display: block;
    margin: 0 !important;
    padding: 0 !important;
    vertical-align: top !important;
    border: none !important;
    outline: none !important;
    line-height: 0 !important;
}

selector .elementor-widget-container {
    padding: 0 !important;
    margin: 0 !important;
    overflow: hidden !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
}

selector .elementor-image {
    overflow: hidden !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
}

/* Remove TODOS os min-height que podem estar interferindo */
selector,
selector *,
selector .elementor-widget,
selector .elementor-element,
selector .elementor-container,
selector .elementor-column,
selector .elementor-widget-container {
    min-height: 0 !important;
    height: auto !important;
}

/* Quando não há imagem, o container some */
selector:empty {
    display: none !important;
    width: 0 !important;
    margin: 0 !important;
}

@media (max-width: 768px) {
    selector {
        width: 30% !important;
        max-width: 100px !important;
        height: auto !important;
        min-height: 0 !important;
        max-height: none !important;
    }
    selector img {
        height: auto !important;
        min-height: 0 !important;
        max-height: none !important;
        max-width: 100px !important;
    }
}

selector {
    padding: 0 !important;
    margin: 0 !important;
    align-self: flex-start !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    align-content: flex-start !important;
    min-height: 90px !important;
    height: auto !important;
}

selector > * {
    margin-top: 0 !important;
    padding-top: 0 !important;
}

@media (max-width: 768px) {
    selector {
        min-height: 75px !important;
    }
}

selector {
    margin: 0 !important;
    padding: 0 !important;
    line-height: 1.3 !important;
    vertical-align: top !important;
}

selector h3,
selector .elementor-heading-title {
    margin: 0 0 2px 0 !important;
    padding: 0 !important;
    line-height: 1.3 !important;
    vertical-align: top !important;
}

selector .elementor-widget-container {
    padding: 0 !important;
    margin: 0 !important;
}

selector {
    margin: 0 !important;
    padding: 0 !important;
}

selector .elementor-widget-container {
    padding: 0 !important;
    margin: 0 !important;
}

selector p {
    margin: 0 !important;
    padding: 0 !important;
}

selector {
    margin: 0 !important;
    padding: 0 !important;
    height: 1px !important;
    min-height: 1px !important;
    max-height: 1px !important;
}

selector .elementor-widget-container {
    margin: 0 !important;
    padding: 0 !important;
    height: 1px !important;
}

selector {
    margin: 0 !important;
    padding: 0 !important;
    height: 1px !important;
}

selector .elementor-widget-container {
    margin: 0 !important;
    padding: 0 !important;
    height: 1px !important;
}

selector hr {
    margin: 0 !important;
    padding: 0 !important;
    height: 1px !important;
}
